--
-- Name: actualizar_fecha_pago(); Type: FUNCTION; Schema: public; Owner: creador
--

CREATE FUNCTION public.actualizar_fecha_pago() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.fecha_pago := NEW.fecha + INTERVAL '1 day' * NEW.dias_credito;
    RETURN NEW;
END;
$$;


